using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class UnitRetryTests
{
    static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
    static NewMilitaryInput Input(WorldSession s,NewMilitaryAction a)=>new(new("request:unit-retry/"+s.Revision+"/"+a),a);
    static void Send(WorldSession s,NewMilitaryAction a,long amount=0){var r=s.DecideNewMilitary(Input(s,a) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
    static WorldSession Ready(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Send(s,NewMilitaryAction.Request);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+30000,a.Y),B=new(a.X+30000,a.Y+16000)},s.PlayerControl,s.Revision).Code);At(s,ArmyEnd(s)+1);return s;}
    static long ArmyEnd(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.Max(r=>r.LastOrDefault()?.EndAt??s.Seconds);
    static WorldSession Failed(bool known=true){var s=Ready();Send(s,NewMilitaryAction.Recall);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);Send(s,NewMilitaryAction.RemoteRecall);var d=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Single();At(s,d.DueAt);Assert.False(s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single().Delivered);if(known)At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single().ReplyDueAt);return s;}
    [Fact]public void RetryRequiresPhysicalFailureKnowledge(){var s=Failed(false);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.RetryRecallHome),s.PlayerControl,s.Revision).Code);Assert.Null(s.DiagnosticSnapshot().NewMilitary!.UnitRetry);}
    [Fact]public void RetryPreservesOriginalAndFirstFailure(){var s=Failed();var before=s.DiagnosticSnapshot();var initial=ContractJson.CanonicalHash(before.NewMilitary!.Withdrawal!);var message=before.Messaging.Messages.Single(m=>m.Kind=="unit-post-order");Send(s,NewMilitaryAction.RetryRecallHome);var w=s.DiagnosticSnapshot();var d=w.NewMilitary!.UnitRetry!.Dispatches.Single();Assert.Equal(message,w.Messaging.Messages.Single(m=>m.Id==message.Id));Assert.Equal(initial,ContractJson.CanonicalHash(w.NewMilitary!.Withdrawal!));Assert.Equal(message.Id,d.Message);Assert.Equal(message.Id+"/attempt/2",d.Attempt);Assert.Equal(NewGameMilitary.Home(w,0),d.Destination);Assert.NotEqual(w.NewMilitary!.Withdrawal!.Dispatches.Single().Id,d.Id);}
    [Fact]public void RetryAppliesOnlyAtPhysicalArrivalAndOnlyOnce(){var s=Failed();int count=s.DiagnosticSnapshot().NewMilitary!.Orders.Length;Send(s,NewMilitaryAction.RetryRecallHome);var d=s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Dispatches.Single();Assert.Equal(count,s.DiagnosticSnapshot().NewMilitary!.Orders.Length);At(s,d.DueAt);var w=s.DiagnosticSnapshot();Assert.Equal(count+1,w.NewMilitary!.Orders.Length);Assert.True(w.NewMilitary.UnitRetry!.Receipts.Single().Applied);Assert.Single(w.Messaging.Receipts,r=>r.MessageId==d.Message);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.RetryRecallHome),s.PlayerControl,s.Revision).Code);At(s,s.Seconds+3);Assert.Equal(count+1,s.DiagnosticSnapshot().NewMilitary!.Orders.Length);}
    [Fact]public void KnownPostRetryDoesNotFollowTrueUnitPosition(){var s=Failed();var w=s.DiagnosticSnapshot();var known=w.NewMilitary!.Withdrawal!.Sightings.Last().Position;Send(s,NewMilitaryAction.RetryRecallKnown);var d=s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Dispatches.Last();Assert.Equal(known,d.Destination);Assert.NotEqual(NewGameMilitary.Position(w,0,s.Seconds),d.Destination);At(s,d.DueAt);Assert.False(s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Receipts.Single().Delivered);}
    [Fact]public void ThreeAttemptLimitNeedsEachFailureReport(){var s=Failed();Send(s,NewMilitaryAction.RetryRecallKnown);var d=s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Dispatches.Last();At(s,d.DueAt);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.RetryRecallKnown),s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Receipts.Last().ReplyDueAt);Send(s,NewMilitaryAction.RetryRecallKnown);d=s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Dispatches.Last();At(s,d.DueAt);At(s,s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Receipts.Last().ReplyDueAt);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.RetryRecallHome),s.PlayerControl,s.Revision).Code);Assert.Equal(3,s.DiagnosticSnapshot().Messaging.Attempts.Count(a=>a.MessageId==d.Message));}
    [Fact]public void DuplicateInputDoesNotCreateAnotherAttempt(){var s=Failed();var i=Input(s,NewMilitaryAction.RetryRecallHome);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.AlreadyAccepted,s.DecideNewMilitary(i,s.PlayerControl,0).Code);Assert.Single(s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Dispatches);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void RestoredRetryHasSameFuture(int step){var s=Failed();Send(s,NewMilitaryAction.RetryRecallHome);var d=s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Dispatches.Single();if(step>0)At(s,d.DueAt);if(step>1)At(s,s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Receipts.Single().ReplyDueAt);if(step>2)At(s,s.Seconds+2);var c=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));long until=s.Seconds+5;foreach(var x in new[]{s,c})At(x,until);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(c.DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void ForgedRetryJournalIsRejected(int kind){var s=Failed();Send(s,NewMilitaryAction.RetryRecallHome);var w=s.DiagnosticSnapshot();var x=w.NewMilitary!.UnitRetry!;if(kind==0)x.Dispatches[0]=x.Dispatches[0] with{Destination=new(0,0)};if(kind==1)x.Dispatches[0]=x.Dispatches[0] with{Attempt=x.Dispatches[0].Message+"/attempt/3"};if(kind==2)w.NewMilitary=w.NewMilitary with{UnitRetry=x with{Dispatches=[..x.Dispatches,x.Dispatches[0]]}};if(kind==3)w.NewMilitary=w.NewMilitary with{UnitRetry=x with{Contract="other"}};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void OldWithdrawalSaveOmitsRetryExtension(){var s=Failed();var text=System.Text.Encoding.UTF8.GetString(ContractJson.Write(s.DiagnosticSnapshot().NewMilitary));Assert.DoesNotContain("UnitRetry",text);Assert.Null(ContractJson.Read<NewMilitaryState>(System.Text.Encoding.UTF8.GetBytes(text)).UnitRetry);}
    [Fact]public void RetryDoesNotRefreshOldCommandPriority(){var s=Failed();Send(s,NewMilitaryAction.Attach);Send(s,NewMilitaryAction.Hold);Send(s,NewMilitaryAction.Withdraw);int n=s.DiagnosticSnapshot().NewMilitary!.Orders.Length;Send(s,NewMilitaryAction.RetryRecallHome);var d=s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Dispatches.Last();At(s,d.DueAt);var r=s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Receipts.Last();Assert.True(r.Delivered);Assert.False(r.Applied);Assert.Equal(n,s.DiagnosticSnapshot().NewMilitary!.Orders.Length);}
    [Fact]public void RetryFailureReplyCanItselfMissDepartedSender(){var s=Failed();Send(s,NewMilitaryAction.RetryRecallKnown);var d=s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Dispatches.Last();At(s,d.DueAt);var w=s.DiagnosticSnapshot();var home=NewGameMilitary.Home(w,0);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=new(home.X+5000,home.Y)},s.PlayerControl,s.Revision).Code);var r=s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Receipts.Last();At(s,r.ReplyDueAt);w=s.DiagnosticSnapshot();Assert.False(w.NewMilitary!.UnitRetry!.Replies.Last().Received);Assert.False(MessageFlow.FailureKnown(w.Messaging,d.Attempt,w.PlayerControl.Value));Assert.False(NewGameMilitary.UnitRetryAllowed(w,NewMilitaryAction.RetryRecallHome));var copy=new WorldSession(ContractJson.Copy(w));Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(copy.DiagnosticSnapshot()));}
}
